import ROUTES from '../../pages/Routes'
import { NavLink } from 'react-router-dom';

import "./Nav.css";


function Nav() {
  return (
    <ul>
      <li>
        <NavLink to={ROUTES.GROUP1}>Group 1</NavLink>
      </li>
      <li>
        <NavLink to={ROUTES.GROUP2}>Group 2</NavLink>
      </li>
      <li>
        <NavLink to={ROUTES.GROUP3} >Group 3</NavLink>
      </li>
    </ul>
  );
}

export default Nav;
